  appearance_frequency, verification_status, tags, exam_type, applicable_exams
) VALUES (
  '航空気象',
  'CBT例題/未分類',
  '大気の気温による鉛直分布の分類で対流圏と成層圏について（a）～（d）のうち、正しいものは いくつあるか。 （１）～（５）の中から選べ。 (a) 地表面から気温が高度とともに減少していく範囲を対流圏といい、地表面は大気を透過した 太陽光線により加熱されることで熱源となり、上空へ熱の反射を行う。 (b) 対流圏では上下の気流の対流が盛んに起こり、雲や雨など天気に密接な関係をもっている。 (c) 成層圏は対流圏の直ぐ上にあり、成層圏下部では温度はほとんど一定(-50℃程度）であるが、 高度 20km 以上では上昇に転じ、約 50km でピークに達する。 (d) 成層圏上部が下部より気温が高いのは、成層圏にある上部の水蒸気が太陽からの紫外線を吸 収するためにおこる。',
  '["１つ", "２つ", "３つ", "４つ"]'::jsonb,
  2,
  NULL,
