INSERT INTO unified_cpl_questions (
  main_subject, sub_subject, question_text, options, correct_answer,
  explanation, source_documents, difficulty_level, importance_score,
  appearance_frequency, verification_status, tags, exam_type, applicable_exams
) VALUES (
  '航空気象',
  'CBT例題/未分類',
  '対流圏における逆転層の成因と特徴について（a）～（d）のうち、正しいものはいくつあるか。 （１）～（５）の中から選べ。 （a）冷気の上に暖気が重なって前線面を作る場合にできる逆転で、前線の存在により下層に寒気、 上層に暖気がくるために発生する前線性逆転がある。 （b）晴れた日などで夜間放射によって地表面の気層が冷却されてできる接地逆転がある。接地逆 転は放射性逆転ともいう。この逆転層は地面から形成され、あまり上空までは発達せず、朝 になって太陽の熱が地面に加わると逆転は解消する。 （c）高気圧の下降気流により空気が沈降し、断熱圧縮の昇温によって地表面から離れた高度にで きる。高気圧下なので通常は晴天であり、上層の乾燥空気で形成されるので逆転層の気温と 露点温度の差は下層に比べて大きく開いている。 （d）対流圏では上空ほど気温が低くなるのが通常であるが、時に上の方が下よりも暖かい層が発 生することがある。これを逆転層という。逆転層では対流が起こらず大気は安定している。',
  '["１つ", "２つ", "３つ", "４つ"]'::jsonb,
  4,
  NULL,
  '{"sources": [{"type": "mlit_sample", "year": 2026, "month": 6, "question_no": 4, "main_subject": "航空気象", "file": "001761087.pdf", "edition": "CPL-airplane-sample"}], "weight": 2.0, "originality": "official", "choice_adaptation": {"from_count": 5, "dropped_index": 5, "dropped_text": "無し", "reason": "drop_fifth_for_four_choice_ui", "correct_unchanged": true}}'::jsonb,
  3,
  6.0,
