INSERT INTO unified_cpl_questions (
  main_subject, sub_subject, question_text, options, correct_answer,
  explanation, source_documents, difficulty_level, importance_score,
  appearance_frequency, verification_status, tags, exam_type, applicable_exams
) VALUES (
  '航空気象',
  'CBT例題/未分類',
  '前線に関する記述（a）～（d）のうち、正しいものはいくつあるか。 （１）～（５）の中から選 べ。 （a）性質の違った二つの気団が隣り合ってできる不連続面を前線面と呼び、この前線面が地上と 交わる線を前線又はフロントという。しかし、この面または線とは、幾何学でいう厳密な面 または線でなく、ある厚さや幅を持っている。 （b）前線面のなす傾斜角はふつう１／５０から１／３００くらいの角度である。前線の傾斜が急 なほど、前線面に起こる空気の鉛直運動が強くなり、雲の発生、発達を促進するので天気へ の影響が大きいことになる。 （c）温暖前線とは寒気団側へ移動する前線のことであり、通常、前線の通過後に気温は上がる。 また、寒冷前線とは暖気団側へ移動する前線であり、通常、前線の通過後に気温は下がる。 （d）前線を境にして気温（密度）、水蒸気の量、風向、風速などの気象要素の幾つかが飛躍的に 異なっている。',
  '["１つ", "２つ", "３つ", "４つ"]'::jsonb,
