INSERT INTO unified_cpl_questions (
  main_subject, sub_subject, question_text, options, correct_answer,
  explanation, source_documents, difficulty_level, importance_score,
  appearance_frequency, verification_status, tags, exam_type, applicable_exams
) VALUES (
  '航空気象',
  'CBT例題/未分類',
  '沿岸前線に関する説明（a）～（d）のうち、正しいものはいくつあるか。 （１）～（５）の中か ら選べ。 （a）地上天気図には描かれない局地的な前線で、低気圧が接近するときに温暖前線の前面（寒気 側）で発生することが多い。 （b）陸上の薄い寒気層（北寄りの弱風）と、その上に流れ込む暖かい空気（南寄りの強風）の境 界に発生するため、前線近傍では風向きが急変するほか、気温の水平傾度が大きい。 （c）沿岸前線の陸側では、暖かく湿った気塊が寒気の上を滑昇するため層状雲が発生し、悪視程 と低シーリングが発生することが多い。沿岸前線近傍の下層では発達した対流雲が発生する こともある。 （d）薄い寒気とその上の暖気との間では風のシアーが大きく、波動が発生している場合がある。 特に、沿岸前線が空港の近くに存在し、上空では南風、空港の地上風は北寄りの風という状 況で南から空港へ進入する場合、かなりの低高度で低層ウィンドシアーや乱気流に遭遇する 可能性を考慮する必要がある。',
  '["１つ", "２つ", "３つ", "４つ"]'::jsonb,
  4,
  NULL,
  '{"sources": [{"type": "mlit_sample", "year": 2026, "month": 6, "question_no": 12, "main_subject": "航空気象", "file": "001761087.pdf", "edition": "CPL-airplane-sample"}], "weight": 2.0, "originality": "official", "choice_adaptation": {"from_count": 5, "dropped_index": 5, "dropped_text": "無し", "reason": "drop_fifth_for_four_choice_ui", "correct_unchanged": true}, "notes": "figure_in_original_pdf"}'::jsonb,
