INSERT INTO unified_cpl_questions (
  main_subject, sub_subject, question_text, options, correct_answer,
  explanation, source_documents, difficulty_level, importance_score,
  appearance_frequency, verification_status, tags, exam_type, applicable_exams
) VALUES (
  '航空気象',
  'CBT例題/未分類',
  '次の運航用飛行場予報気象通報式（TAF）の説明（a）～（d）のうち、正しいものはいくつある か。 （１）～（５）の中から選べ。 RJFF 040513Z 0406 / 0512 12007KT 9999 -SHRA FEW015 SCT020 BKN040 BECMG 0413 / 0415 13015G30 KT TEMPO 0414 / 0416 3000 SHRA BR BKN015 TEMPO 0416 / 0421 1500 +SHRA BR BKN010 BECMG 0500 / 0503 30012 KT TEMPO 0503 / 0506 29015G25 KT （a）日本時間 4 日午後 9 時の風向風速 は 120 度 7 ノットが予想されている。 （b）日本時間 5 日午前 1 時には一時的に最大 30 ノットの風が予報されている。 （c）日本時間 5 日午前 5 時には一時的に強いしゅう雨が予報されている。 （d）日本時間 5 日午後 6 時には 300 度 12 ノットの風が予報されている。 （１）１つ （２）２つ （３）３つ （４）４つ',
